const isOfType = (type: string) => (item: Item): boolean => item.type === type;

// A policy only covers what it insures, so a damage entry naming an item the
// policy does not carry is a rejection rather than a zero-value payout.
//
// This subsumes the unknown-item-type case, and deliberately so: the claim path
// never consults ITEM_CATALOGUE. Coverage is the stronger check — a policy can
// only hold items that passed `catalogueEntryOf` when it was quoted, so a type
// nobody insures is necessarily not among `policyItems` and is rejected here,
// by name. Adding a catalogue lookup on this path would be dead code: it could
// only fire on inputs that this lookup already rejects, and it would report the
// weaker of the two reasons ("unknown type" when the actionable fact is that
// the policy does not cover it).
//
// A damage entry carries no identity beyond its type, so the nth damage of a
// type is settled against the nth insured item of that type. Each entry
// consumes one insured item, so claiming more of a type than the policy covers
// runs out of items and is rejected here too.
const damagedItem = (
  damage: Damage,
  policyItems: Item[],
  alreadyDamagedOfType: number,
): Item => {
  const item =
    policyItems.filter(isOfType(damage.itemType))[alreadyDamagedOfType];
  if (item === undefined) {
    throw new ClaimOfficeError(
      `Damaged item is not covered by the policy: ${damage.itemType}`,
    );
  }
  return item;
};

const countOfTypeBefore = (damages: Damage[], index: number): number =>
  damages
    .slice(0, index)
    .filter((earlier) => earlier.itemType === damages[index].itemType).length;

// The deductible applies once per damaged item, so each damage entry is
// reduced separately before the entries are summed. A damage entry names its
// item by type, so the clauses are read off the matching insured item.
const incidentPayout = (incident: Incident, policyItems: Item[]): number =>
  Math.floor(
    sum(
      incident.damages.map((damage, index) =>
        damagePayout(
          damage,
          damagedItem(
            damage,
            policyItems,
            countOfTypeBefore(incident.damages, index),
          ),
        ),
      ),
    ),
  );

